export const imageFixture = format => Buffer.from(encoded[format], "base64");
export function createPng({ width = 3, height = 2, data, color = [224, 59, 82, 255] } = {}) {
  const pixels = data ?? Buffer.from(Array.from({ length: width * height }, () => color).flat());
  return PNG.sync.write({ width, height, data: pixels });
}
export function decodePng(bytes) {
  const decoded = PNG.sync.read(bytes, { checkCRC: true });
  return { width: decoded.width, height: decoded.height, data: decoded.data };
}

export function assertPixelsClose(actual, expected, maxDelta, label) {
  assert.equal(actual.length, expected.length, label);
  for (let index = 0; index < actual.length; index++) {
    // Independent color managers can round RGB differently; alpha is never transformed.
    if (index % 4 === 3) assert.equal(actual[index], expected[index], `${label} alpha ${index}`);
    else assert.ok(Math.abs(actual[index] - expected[index]) <= maxDelta, `${label} channel ${index}`);
  }
}

export function pngChunkTypes(bytes) {
  assertPng(bytes);
  const types = [];
  for (let at = 8; at < bytes.length;) {
    if (at + 12 > bytes.length) throw new Error("truncated PNG chunk");
    const size = bytes.readUInt32BE(at);
    if (size > bytes.length - at - 12) throw new Error("truncated PNG data");
    types.push(bytes.toString("ascii", at + 4, at + 8));
    at += size + 12;
  }
  return types;
}
export function assertFreshPng(bytes) {
  if (!pngChunkTypes(bytes).every(type => ["IHDR", "IDAT", "IEND"].includes(type))) throw new Error("unexpected PNG metadata");
  return decodePng(bytes);
}
function assertPng(bytes) {
  if (!bytes.subarray(0, 8).equals(Buffer.from([137,80,78,71,13,10,26,10]))) throw new Error("not PNG");
}
